<?php $v = fn($k, $d = '') => $p[$k] ?? $d; $er = fn($k) => $errors[$k] ?? null; $id = (int)($p['id'] ?? 0); ?>
<form method="post" enctype="multipart/form-data" action="<?= e(url('/admin/products/save')) ?>" class="grid lg:grid-cols-3 gap-4" data-once><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>">
<div class="lg:col-span-2 space-y-4"><div class="card p-5 grid sm:grid-cols-2 gap-4"><h2 class="font-bold sm:col-span-2">Basic details</h2>
  <div class="sm:col-span-2"><label class="label" for="name">Product name *</label><input class="input <?= $er('name') ? 'has-error' : '' ?>" id="name" name="name" value="<?= e($v('name')) ?>" required maxlength="190"><?php if ($er('name')): ?><p class="err"><?= e($er('name')) ?></p><?php endif; ?></div>
  <div class="sm:col-span-2"><label class="label" for="name_ta">Tamil name (optional)</label><input class="input" id="name_ta" name="name_ta" value="<?= e($v('name_ta')) ?>" maxlength="190" placeholder="பூந்தொட்டி"><p class="hint">Shown to customers and used by Voice Order.</p></div>
  <div><label class="label" for="sku">Product ID / SKU *</label><input class="input font-mono uppercase <?= $er('sku') ? 'has-error' : '' ?>" id="sku" name="sku" value="<?= e($v('sku')) ?>" required maxlength="60"><?php if ($er('sku')): ?><p class="err"><?= e($er('sku')) ?></p><?php endif; ?></div>
  <div><label class="label" for="category_id">Category *</label><select class="select <?= $er('category_id') ? 'has-error' : '' ?>" id="category_id" name="category_id" required><option value="">Select…</option><?php foreach ($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$v('category_id') === (int)$c['id'] ? 'selected' : '' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><?php if ($er('category_id')): ?><p class="err"><?= e($er('category_id')) ?></p><?php endif; ?><?php if (!$categories): ?><p class="err">Create a category first.</p><?php endif; ?></div>
  <div class="sm:col-span-2"><label class="label" for="description">Description</label><textarea class="textarea" id="description" name="description" rows="4"><?= e($v('description')) ?></textarea></div>
  <div class="sm:col-span-2"><label class="label" for="safety_notes">Product safety notes</label><textarea class="textarea !min-h-[80px]" id="safety_notes" name="safety_notes"><?= e($v('safety_notes')) ?></textarea></div>
  <div class="sm:col-span-2"><label class="label" for="aliases">Voice Order aliases (comma separated, include Tamil names)</label><input class="input" id="aliases" name="aliases" value="<?= e($v('aliases')) ?>" placeholder="flower pot, flower pots, பூந்தொட்டி"><p class="hint">Helps Voice Order match what customers say to this product.</p></div></div>
 <div class="card p-5"><h2 class="font-bold mb-3">Images</h2>
  <?php if ($images): ?><div class="flex flex-wrap gap-3 mb-4"><?php foreach ($images as $im): ?><div class="w-28 text-xs"><img src="<?= e(upload_url($im['path'])) ?>" class="w-28 h-28 object-cover rounded-lg border" alt=""><label class="flex items-center gap-1 mt-1"><input type="radio" name="primary_image" value="<?= (int)$im['id'] ?>" <?= $im['is_primary'] ? 'checked' : '' ?>> Primary</label><label class="flex items-center gap-1 text-red-700"><input type="checkbox" name="remove_images[]" value="<?= (int)$im['id'] ?>"> Remove</label></div><?php endforeach; ?></div><?php endif; ?>
  <label class="label" for="images">Upload images</label><input type="file" id="images" name="images[]" multiple accept="image/jpeg,image/png,image/webp" class="block text-sm"><p class="hint">JPG/PNG/WebP, max 6 MB each. Images are re-encoded and resized for safety and speed.</p>
  <div class="mt-4" data-multi-picker><button type="button" data-open-picker class="btn btn-soft btn-sm"><?= icon('images', 'w-4 h-4') ?> Add from Media Library (incl. AI images)</button><div data-selected class="flex flex-wrap gap-2 mt-3"></div></div></div></div>
<div class="space-y-4"><div class="card p-5 space-y-4"><h2 class="font-bold">Pricing & stock</h2>
  <div><label class="label" for="original_price">Original price (MRP, ₹) *</label><input class="input <?= $er('original_price') ? 'has-error' : '' ?>" id="original_price" name="original_price" type="number" step="0.01" min="0.01" value="<?= e($v('original_price')) ?>" required><?php if ($er('original_price')): ?><p class="err"><?= e($er('original_price')) ?></p><?php endif; ?></div>
  <div><label class="label" for="selling_price">Selling price (₹) *</label><input class="input <?= $er('selling_price') ? 'has-error' : '' ?>" id="selling_price" name="selling_price" type="number" step="0.01" min="0.01" value="<?= e($v('selling_price')) ?>" required><?php if ($er('selling_price')): ?><p class="err"><?= e($er('selling_price')) ?></p><?php endif; ?><p class="hint" id="disc-hint">Discount % is calculated automatically.</p></div>
  <div class="grid grid-cols-2 gap-3"><div><label class="label" for="stock">Stock *</label><input class="input <?= $er('stock') ? 'has-error' : '' ?>" id="stock" name="stock" type="number" min="0" value="<?= e($v('stock', 0)) ?>" required></div><div><label class="label" for="low_stock_threshold">Low-stock alert at</label><input class="input" id="low_stock_threshold" name="low_stock_threshold" type="number" min="0" value="<?= e($v('low_stock_threshold', 10)) ?>"></div></div></div>
 <div class="card p-5 space-y-3"><h2 class="font-bold">Visibility</h2><div><label class="label" for="status">Status</label><select class="select" id="status" name="status"><?php foreach (['active', 'inactive', 'archived'] as $s): ?><option <?= $v('status', 'active') === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select><p class="hint">Only “active” products are visible to customers.</p></div>
  <label class="flex items-center gap-2 text-sm"><input type="checkbox" name="is_featured" value="1" <?= $v('is_featured') ? 'checked' : '' ?>> Featured on homepage</label><label class="flex items-center gap-2 text-sm"><input type="checkbox" name="is_popular" value="1" <?= $v('is_popular') ? 'checked' : '' ?>> Popular on homepage</label></div>
 <div class="flex gap-2"><button class="btn btn-primary flex-1">Save product</button><a class="btn btn-outline" href="<?= e(url('/admin/products')) ?>">Cancel</a></div></div></form>
<script>(()=>{const o=document.getElementById('original_price'),s=document.getElementById('selling_price'),h=document.getElementById('disc-hint');const u=()=>{const a=+o.value,b=+s.value;h.textContent=a>0&&b>0&&b<=a?'Discount: '+((a-b)/a*100).toFixed(1)+'%':'Discount % is calculated automatically.'};o.oninput=s.oninput=u;u()})()</script>
